import heapq

def {{fn_name}}(graph, src, dst):
    dist = {n: float('inf') for n in graph}
    dist[src] = 0
    prev = {}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == dst: break
        if d > dist[u]: continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))
    if dist[dst] == float('inf'): return None
    path = [dst]
    while path[-1] in prev:
        path.append(prev[path[-1]])
    return list(reversed(path)), dist[dst]
